SELECT i.last_restock, i.store_id, i.product_id, ss.store_id AS store_sale_store_id, ss.units, ss.revenue, DATEDIFF(CURRENT_DATE(), i.last_restock) AS days_since_last_restock FROM inventory i LEFT JOIN store_sales ss ON i.store_id = ss.store_id AND i.product_id = ss.product_id WHERE ss.revenue <= 2000 OR i.product_id IN (1, 3, 6);
